  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [10] db_index.sen

  gszaMungedText[10] =
    "\" munged db_index.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_index.sen -- index related words                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" db_index.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* \\index is the category to identify indexes                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\index \\\\category ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if word is an index (is of \\index category)                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word.isaIndex params| pwIndex |\n"
    "\n"
    "  pwIndex word.category@ find: \\index eql\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if current folder has the name \"indexes\" (i.e. is ../indexes)          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder[].isIndexes ( t | f )\n"
    "\n"
    "  folder[] dic.name@ \"indexes\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the indexes folder and push it onto task dictionary                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": path[].pushIndexesFolder ( -- )\n"
    "\n"
    "  \"indexes\" find execute path[].pushFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the indexes folder (which was pushed by path[].pushIndexesFolder)      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": path[].popIndexesFolder ( -- )\n"
    "\n"
    "  path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if in an indexes folder                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::folderIsIndexes ( t | ec f )\n"
    "\n"
    "  folder[].isIndexes if true exit then\n"
    "\n"
    "  EC_NOT_IN_INDEXES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is not known (specifically not a known index)                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::nameIsUnknownIndex params| sIndexNm | ( t | ec f )\n"
    "\n"
    "  sIndexNm folder[].findSymbol not if true exit then\n"
    "  EC_INDEX_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check given name is the name of a word of \\index category               EC */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::nameIsaIndex params| sIndexNm | ( t | ec f )\n"
    "\n"
    "  sIndexNm find locals| pwIndex |\n"
    "\n"
    "  pwIndex not if EC_NO_SUCH_INDEX false exit then\n"
    "\n"
    "  pwIndex word.category@ find: \\index eql if true exit then\n"
    "\n"
    "  EC_NOT_AN_INDEX false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if sTableNm . sIndexNm is a valid index assembly                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::validIndexAssembly params| sTableNm sIndexNm |  ( t | ec f )\n"
    "\n"
    "  // should be in the tables folder\n"
    "  check::folderIsTables not if false exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm check::folderHasNamedTable not if false exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table dictionary\n"
    "  sTableNm path[].pushNamedTableFolder\n"
    "\n"
    "// push indexes folder\n"
    "  path[].pushIndexesFolder\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check it is an index we are dropping\n"
    "  sIndexNm check::nameIsaIndex not if\n"
    "    path[].popIndexesFolder\n"
    "    path[].popNamedTableFolder\n"
    "    folder[].isTables assert\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  path[].popIndexesFolder\n"
    "  path[].popNamedTableFolder\n"
    "  folder[].isTables assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                   -- Supplemental Create Table Support --                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an indexes folder under given named table foler                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::makeIndexesAssembly params| sTableNm |\n"
    "\n"
    "/*\n"
    " * called from : table::makeTableAssembly\n"
    " */\n"
    "\n"
    "  args.tracepoint if\n"
    "    \"MAKING INDEXES FOR TABLE \" sTableNm str.cat\n"
    "      \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  sTableNm find execute locals| pTableFolder |\n"
    "  \"indexes\" pTableFolder folder::makeSubFolder\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                          -- Create Index Support --                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* new a C++ Index instance using given table name                   EMBEDDED */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::newIndex params| sIndexNm |\n"
    "\n"
    "  folder[].isIndexes assert\n"
    "\n"
    "  find: \\index locals| pwIndexCatg |\n"
    "\n"
    "  sIndexNm index::new locals| pIndex |\n"
    "\n"
    "  sIndexNm word::new locals| pwIndex |\n"
    "\n"
    "  pwIndexCatg pIndex pwIndex word.cppObject!\n"
    "\n"
    "  //pwIndex word.see\n"
    "\n"
    "  pwIndex execute locals| pIndex |\n"
    "\n"
    "  pIndex\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an index assembly for given table                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::makeIndexAssembly params| pTable sIndexNm pIndexDef |\n"
    "\n"
    "  sIndexNm index::newIndex locals| pIndex |\n"
    "\n"
    "  pIndexDef pIndex index.indexDef!\n"
    "  pTable pIndex index.table!\n"
    "\n"
    "  pIndex pTable table.addIndex\n"
    "\n"
    "  pIndex\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index using given index definition                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::createIndex params| pTable sIndexNm pIndexDef |\n"
    "\n"
    "  folder[].isIndexes assert\n"
    "\n"
    "  pIndexDef sIndexNm pTable index::makeIndexAssembly locals| pIndex |\n"
    "\n"
    "  pIndex\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                           -- Drop Index Support --                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* delete C++ Index object & its forget word                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::deleteIndex params| sIndexNm |\n"
    "\n"
    "  sIndexNm find execute index::delete\n"
    "\n"
    "  sIndexNm :forget\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop an index (delete index tress in table, and forget word)               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::removeIndexAssembly params| sTableNm sIndexNm |\n"
    "\n"
    "  0 locals| pIndex |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // remove the index from the table\n"
    "  sIndexNm find execute to pIndex\n"
    "  pIndex pIndex index.table@ table.deleteIndex\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // tidy up the index and forget it\n"
    "  sIndexNm index::deleteIndex\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop an index (delete index tress in table, and forget word)               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::dropIndex params| sTableNm sIndexNm |\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm path[].pushNamedTableFolder\n"
    "\n"
    "  // push indexes folder\n"
    "  path[].pushIndexesFolder\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  sIndexNm sTableNm index::removeIndexAssembly\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // pop indexes folder\n"
    "  path[].popIndexesFolder\n"
    "\n"
    "  // pop table folder\n"
    "  path[].popNamedTableFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                    -- Supplemental Drop Table Support --                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* delete all the indexes of a table                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::deleteAllIndexes params| pFolder |\n"
    "\n"
    "  0 locals| sIndexNm |\n"
    "\n"
    "  pFolder dic.lastWord not if  exit_rt then\n"
    "\n"
    "  pFolder path[].pushFolder\n"
    "\n"
    "  begin\n"
    "\n"
    "    pFolder dic.lastWord word.name@ to sIndexNm\n"
    "\n"
    "    // delete Index object and forget index word\n"
    "    sIndexNm index::deleteIndex\n"
    " \n"
    "    pFolder dic.lastWord not until\n"
    "\n"
    "  path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove the indexes folder (and contents) for assumed table                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index::removeIndexesAssembly\n"
    "\n"
    " /*\n"
    "  * This wil be called from : table::removeTableAssembly\n"
    "  *\n"
    "  * At this stage the table (and its indexes) will have been truncated\n"
    "  */\n"
    "\n"
    "  // delete and forget all indexes\n"
    "  \"indexes\" find execute index::deleteAllIndexes\n"
    "\n"
    "  // forget the indexes folder itself\n"
    "  \"indexes\" folder::remove\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

