  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [23] OP_sizeIndex.sen

  gszaMungedText[23] =
    "\" munged OP_sizeIndex.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_sizeIndex.sen -- Operator size index                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_sizeIndex.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": szidx_action\n"
    "\n"
    "  <tableNm> <indexNm> op__table_index not if\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // find the __ table\n"
    "  <streamDef> op__tableDef_streamSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  streamSetTable[] streamDef[].new\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  streamDef[].pipeOut\n"
    "\n"
    "  // create an infoSet operand\n"
    "  streamSetTable[] StreamSet[].new\n"
    "\n"
    "  0 index[].size number.magnitude >str\n"
    "\n"
    "  // insert index size\n"
    "  streamSetTable[] StreamSet[].addSizeIndex assert\n"
    "\n"
    "  // pipeout the infoset\n"
    "  StreamSet[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: szidx :: szidx <tableNm> <indexNm> ;\n"
    "\n"
    ": szidx _cmdTags tagCopy: liteOp_tags\n"
    "  tags{\n"
    "    <cmdDesc>   = \"--desc for op--\"\n"
    "    <streamDef> = __sizeIndex\n"
    "    <params>    = 2\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

