  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [24] OP_fetch.sen

  gszaMungedText[24] =
    "\" munged OP_fetch.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_fetch.sen -- Operator fetch                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_fetch.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position and begin fetch                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": positionBeginFetch ( \"iPhrase\" \"lowerKey\" \"upperKey\" )\n"
    "\n"
    "  params| upperKey lowerKey iPhrase |\n"
    "  0 locals| sIndexNm |\n"
    "\n"
    "  // find the index\n"
    "  iPhrase planner[].indexNm@ to sIndexNm\n"
    "  <tableNm> sIndexNm op__index assert\n"
    "\n"
    "  // grab the table ptn read lock\n"
    "  tablePtn[] tablePtnGrabRead\n"
    "\n"
    "  // new an index stream\n"
    "  index[] tablePtn[] indexStream::new to indexStream[]\n"
    "\n"
    "  // open index stream to access index\n"
    "  indexStream[].open\n"
    "\n"
    "  // position in the index\n"
    "  iPhrase  // phrase\n"
    "  lowerKey // lower\n"
    "  upperKey // upper\n"
    "  planner[] indexStream[].seek\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch first buffer for phrase                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchFirstBuffer ( iPhrase -- )\n"
    "\n"
    "  params| iPhrase |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the fetch technique\n"
    "  iPhrase planner[].fetchTechnique@\n"
    "\n"
    "  case\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an exact select using index\n"
    "    AT_EXACT of\n"
    "      \"*exact*\" .verbose\n"
    "\n"
    "      iPhrase                  // phrase\n"
    "      iPhrase planner[].key@   // lower key\n"
    "      iPhrase planner[].key@   // upper key\n"
    "      positionBeginFetch\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // lower bound select using index\n"
    "    AT_LOWER of\n"
    "      \"*lower*\" .verbose\n"
    "\n"
    "      iPhrase                     // phrase\n"
    "      iPhrase planner[].lowKey@   // lower key\n"
    "      \"\"                          // upper key\n"
    "      positionBeginFetch\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an upper bound select using index\n"
    "    AT_UPPER of\n"
    "      \"*upper*\" .verbose\n"
    "\n"
    "      iPhrase                     // phrase\n"
    "      \"\"                          // lower key\n"
    "      iPhrase planner[].upperKey@ // upper key\n"
    "      positionBeginFetch\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // a range select using index\n"
    "    AT_RANGE of\n"
    "      \"*range\" .verbose\n"
    "\n"
    "      iPhrase                     // phrase\n"
    "      iPhrase planner[].lowKey@   // lower key\n"
    "      iPhrase planner[].upperKey@ // upper key\n"
    "      positionBeginFetch\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // full scan (no index)\n"
    "    AT_SCAN of\n"
    "      \"*scan*\" .verbose\n"
    "      // now get excat key rows from index\n"
    "      tablePtn[] tablePtnGrabRead\n"
    "      tablePtn[] ptnStream::new to ptnStream[]\n"
    "\n"
    "      // open ptn stream for the tablePtn\n"
    "      ptnStream[] ptnStream.open assert\n"
    "\n"
    "    endof\n"
    "\n"
    "  endcase\n"
    "\n"
    "  // force op loop to call fetch_CrwBuffer to start processing buffers\n"
    "  \"fetch_CrwBuffer\" word::find LogicUnit[].handler!\n"
    "  true LogicUnit[].callAgain!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate plan for the fetch                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": generatePlan ( -- )\n"
    "\n"
    "  0 locals| sPredicate |\n"
    "\n"
    "  //sWhere \"generatePlan\" \"%v %v\" str.format .\n"
    "\n"
    "  ( cdt_0 ) planner[].new\n"
    "  ( cdt_1 ) Table[] Planner[].table!\n"
    "\n"
    "  ( cdt_2 ) <predicate> Planner[].parseWhere  //\"parseWheres\" .\n"
    "\n"
    "  ( cdt_3 ) Planner[].genPaths           //\"genPaths\" .\n"
    "  ( cdt_4 ) Planner[].scorePaths         //\"scorePaths\" .\n"
    "  //( cdt_5 ) Planner[].showPaths\n"
    "\n"
    "  ( cdt_6 ) Planner[].matchPaths         //\"matchPaths\" .\n"
    "  //( cdt_6 ) Planner[].showPaths\n"
    "\n"
    "  ( cdt_7 ) Planner[].choosePaths        //\"choosePaths\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CANCELMARKER ...                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetch_CancelMarker \\handler\n"
    "\n"
    "  //\"ZK_CANCELMARKER_handler\" .verbose\n"
    "  nullptr to Operand[]\n"
    "  PipeIn[].pipeOut\n"
    "  Op.ackPipelineJob\n"
    "\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CRWBUFFER ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetch_CrwBuffer \\handler\n"
    " \n"
    "  //\"Operand:- ZK_CRWBUFFER\" .verbose\n"
    "\n"
    "  // get the fetchTechnique\n"
    "  Counter1[] planner[].fetchTechnique@\n"
    "  case\n"
    "    AT_SCAN of\n"
    "      // read next buffer from ptn stream\n"
    "      ptnStream[] ptnStream.read to Operand[]\n"
    "    endof\n"
    "\n"
    "    // all other types of fetches, just fetchNext\n"
    "    rowOnce[].isNull if\n"
    "      nullptr\n"
    "    else\n"
    "      rowOnce[]\n"
    "    then\n"
    "    indexStream[].read to Operand[]\n"
    "\n"
    "  endcase\n"
    "\n"
    "  // no more data for counter1[] phrase ?\n"
    "  Operand[].isNull if\n"
    "\n"
    "    // any more phrases ?\n"
    "    Counter1[] 1 + to Counter1[]\n"
    "    Counter1[] Counter0[] >= if\n"
    "      // all done\n"
    "      // close and delete partition stream\n"
    "      ptnStream[].isNull not if\n"
    "        ptnStream[] ptnStream.close\n"
    "        ptnStream[] ptnStream.delete\n"
    "        nullptr to ptnStream[]\n"
    "      then\n"
    " \n"
    "      // close and delete index stream\n"
    "      indexStream[].isNull not if\n"
    "        indexStream[].close\n"
    "        indexStream[].delete\n"
    "        nullptr to indexStream[]\n"
    "      then\n"
    " \n"
    "      tablePtn[] tablePtnDropRead\n"
    "\n"
    "      // delete the planner\n"
    "      planner[].delete\n"
    "\n"
    "      // delete the rowOnce skipList\n"
    "      rowOnce[].isNull not if\n"
    "        rowOnce[].delete\n"
    "      then\n"
    "\n"
    "      // pipeout an eosMarker\n"
    "      Operand[].newEosMarker\n"
    "      Operand[].pipeOut\n"
    "    else\n"
    "      // position and fetch first buffer for next phrase\n"
    "      Counter1[] fetchFirstBuffer\n"
    "    then\n"
    " \n"
    "  else\n"
    " \n"
    "    // pipe out the read crw buffer\n"
    "    Operand[].pipeOut\n"
    " \n"
    "    // call this handler again to process next buffer\n"
    "    true LogicUnit[].callAgain!\n"
    " \n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_DATAPULSE ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetch_DataMarker \\handler\n"
    " \n"
    "  0 locals| iPhrases |\n"
    "\n"
    "  //\"Operand:- ZK_DATAPULSE\" .verbose\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  // new a stream def\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get no of phrases\n"
    "  planner[].phrases@ to Counter0[]\n"
    "\n"
    "  // if multiple phrases create a rowOnce skipList\n"
    "  Counter0[] 1 > if\n"
    "    RowOnce[].new\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // assert we have at least one phrase\n"
    "  Counter0[] 1 >= assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set counter1[] to 0\n"
    "  0 to Counter1[]\n"
    " \n"
    "  // position and fetch the first buffer for the first phrase\n"
    "  Counter1[] fetchFirstBuffer\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetch_StartMarker \\handler\n"
    "\n"
    "  //\"Operand:- ZK_STARTMARKER\" .verbose\n"
    "\n"
    "  0 locals| iPhrases |\n"
    "\n"
    "  <tableNm> op__table if\n"
    "    Table[].tablePtn@ to tablePtn[]\n"
    "    PipeIn[].pipeOut\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // generate the plan for the fetch\n"
    "  generatePlan\n"
    "\n"
    "  //planner[].showPaths\n"
    "\n"
    "  // assert we have a plan\n"
    "  planner[].isNull not assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch request                                      (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetch_req \\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "  //<tableNm> <predicate> \"PARAMETERS %v %v\" str.format .\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: fetch_CancelMarker ZK_CANCELMARKER op[].handler!\n"
    "  find: fetch_CrwBuffer    ZK_CRWBUFFER    op[].handler!\n"
    "  find: fetch_DataMarker  ZK_DATAPULSE  op[].handler!\n"
    "  find: fetch_StartMarker  ZK_STARTMARKER  op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: fetch :: fetch <tableNm> <predicate> ;\n"
    "\n"
    ": fetch _cmdTags tagCopy: op_tags\n"
    "  tags{ <cmdDesc> = \"--desc for op--\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 24 CONSTANT OP_fetch.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

