  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [30] OP_tableSizes.sen

  gszaMungedText[30] =
    "\" munged OP_tableSizes.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_tableSizes.sen -- Operator table sizes                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_tableSizes.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableSizes_action\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in the tables folder\n"
    "  check::folderIsTables not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    PipeIn[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeOut\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  0 locals| sTableNm |\n"
    "\n"
    "  // find the __ table\n"
    "  <streamDef> op__tableDef_streamSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  streamSetTable[] streamDef[].new\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  streamDef[].pipeOut\n"
    "\n"
    "  // create an infoSet operand\n"
    "  streamSetTable[] StreamSet[].new\n"
    "\n"
    "  folder[] dic.lastWord dup\n"
    "  iterate\n"
    "\n"
    "    object@ word.name@ to sTableNm\n"
    "\n"
    "    // get size ofthe table\n"
    "    sTableNm op__table not if\n"
    "      false\n"
    "      exit\n"
    "    then\n"
    "\n"
    "    // skip definition only tables\n"
    "    Table[].isDefinitionOnly@ not if\n"
    "\n"
    "      0 Table[].size number.magnitude >str\n"
    "\n"
    "      // insert index size\n"
    "      sTableNm streamSetTable[] StreamSet[].addTableSizes  not if\n"
    "        StreamSet[].pipeOut\n"
    "        streamSetTable[] streamSet[].new\n"
    "        sTableNm streamSetTable[] StreamSet[].addTableSizes assert\n"
    "      then\n"
    "\n"
    "    then\n"
    "\n"
    "    // move to next table\n"
    "    nullptr to Table[]\n"
    "\n"
    "    object@ word.prev object!\n"
    "\n"
    "  next\n"
    "\n"
    "  // pipeout the infoset\n"
    "  StreamSet[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: tableSizes :: tableSizes ;\n"
    "\n"
    ": tableSizes _cmdTags tagCopy: liteOp_tags\n"
    "  tags{\n"
    "    <cmdDesc>   = \"--desc for op--\"\n"
    "    <streamDef> = __tableSizes\n"
    "    <params>    = 0\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

