    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lsidxcol_action\n"
    "\n"
    "  0 locals| iColumns |\n"
    "\n"
    "  // find the table\n"
    "  <tableNm> <indexNm> op__table_index not if\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // find the __ table\n"
    "  <streamDef> op__tableDef_streamSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  streamSetTable[] streamDef[].new\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  streamDef[].pipeOut\n"
    "\n"
    "  // create an infoSet operand\n"
    "  streamSetTable[] StreamSet[].new\n"
    "\n"
    "  // get no of columns in the index\n"
    "  index[].columnCount@ to iColumns\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // insert a row in the infoSet for each index column\n"
    "  iColumns 0 do\n"
    "    I index[].column@\n"
    "    streamSetTable[] StreamSet[].addColumnDef  not if\n"
    "      StreamSet[].pipeOut\n"
    "      streamSetTable[] streamSet[].new\n"
    "      I index[].column@\n"
    "      streamSetTable[] StreamSet[].addColumnDef assert\n"
    "    then\n"
    "  loop\n"
    "\n"
    "  // pipeout the infoset\n"
    "  StreamSet[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: lsidxcol :: lsidxcol <tableNm> <indexNm> ;\n"
    "\n"
    ": lsidxcol _cmdTags tagCopy: localLiteOp_tags\n"
    "  tags{\n"
    "    <cmdDesc>     = \"--desc for op--\"\n"
    "    <streamDef>   = __listColumns\n"
    "    <params>      = 2\n"
    "  }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

