  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [85] se_categories.sen

  gszaMungedText[85] =
    "\" munged se_categories.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_categories.sen -- categories                                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" se_categories.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* categorising word                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\\\category immediate\n"
    "\n"
    "  //\n"
    "  // this word is used while compiling another word.\n"
    "  // let us call that another word the catgWord.\n"
    "  // this word sets the catgWord being compiled to be an immediate word.\n"
    "  // that catgWord is then later used to set yet another word being comiled\n"
    "  //   to have the category of catgWord.\n"
    "  // let us call that yet another word the targetWord\n"
    "  //\n"
    "\n"
    "  // while compiling a new catgWord set the catgWord to be immediate\n"
    "  true\n"
    "  compiler::current@\n"
    "  word.immediate!\n"
    "\n"
    "  // add code into the catgWord so that when catgWord ised used while compiling\n"
    "  // the target word, the category of the target word is set to be catgWord\n"
    "  compiler::current@ encode::push\n"
    "  POSTPONE compiler::current@\n"
    "  POSTPONE word.category!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* prompt category                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\prompt \\\\category ;\n"
    "\n"
    ": prompts \\prompt find: \\prompt word::ofCatg ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* demon category                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\demon \\\\category ;\n"
    "\n"
    ": demons \\prompt find: \\demon word::ofCatg ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* folder is used as a kind of word to identify folders                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\folder \\\\category ;\n"
    "\n"
    ": isFolder word.category@ find: \\folder eql ;\n"
    "\n"
    ": folders \\prompt find: \\folder word::ofCatg ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler category                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\handler \\\\category ;\n"
    "\n"
    ": handlers \\prompt find: \\handler word::ofCatg ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* include category                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\include \\\\category ;\n"
    "\n"
    ": includes \\prompt find: \\include word::ofCatg ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* operator category                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\operator \\\\category ;\n"
    "\n"
    ": operators \\prompt find: \\operator word::ofCatg ;\n"
    ": ops       \\prompt find: \\operator word::ofCatg ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* procedure category                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\procedure \\\\category ;\n"
    "\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words in the current dictionary                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": words \\prompt\n"
    "\n"
    "  iterate-words\n"
    "    word@ word.name@ str.length word@ word.name@ \"word: %32v %v\" .printf\n"
    "  next-word\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lw \\prompt\n"
    "\n"
    "  0 0 locals| pWord pCatg |\n"
    "\n"
    "  dic::root dic.lastWord dup\n"
    "  iterate                                 // iterate word cursor\n"
    "\n"
    "    object@ to pWord\n"
    "\n"
    "    pWord word.show\n"
    "\n"
    "    object@ word.prev object!             // advance cursor backwards thru words\n"
    "  next\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 85 CONSTANT se_categories.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [86] OP_scan.sen

  gszaMungedText[86] =
    "\" munged OP_scan.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_scan.sen -- Operator scan                                               */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_scan.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CANCELMARKER ...                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Scan_CancelMarker \\handler\n"
    "\n"
    "  nullptr to Operand[]\n"
    "  PipeIn[].pipeOut\n"
    "  Op.ackPipelineJob\n"
    "  false\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CRWBUFFER ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "// \": scan_CrwBuffer\" .\n"
    "\n"
    ": scan_CrwBuffer \\handler\n"
    "  \n"
    "  debug::flag@ if \"(Revised) scan_CrwBuffer handler\" . then\n"
    "\n"
    "  // read next buffer from ptn stream\n"
    "  ptnStream[] ptnStream.read to Operand[]\n"
    " \n"
    "  Operand[].isNotNull if\n"
    "    // read a next crw buffer\n"
    "\n"
    "    // pipe out the read crw buffer\n"
    "    Operand[].pipeOut\n"
    " \n"
    "    // call this handler again to process next buffer\n"
    "    true LogicUnit[].callAgain!\n"
    " \n"
    "  else\n"
    "    // no more crw buffers\n"
    " \n"
    "    // close and delete partition stream\n"
    "    ptnStream[] ptnStream.close\n"
    "    ptnStream[] ptnStream.delete\n"
    "    nullptr to ptnStream[]\n"
    " \n"
    "    // drop partition lock\n"
    "    tablePtn[] tablePtnDropRead\n"
    " \n"
    "    // pipe out an eos marker\n"
    "    Operand[].newEosMarker\n"
    "    Operand[].pipeOut\n"
    "\n"
    "  then\n"
    " \n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    " \n"
    "  // check for rate metering\n"
    " \n"
    "  0 locals| rateSecs |\n"
    "\n"
    "  \"<rateSecs>\" job[] job.tagSet@ tagSet.hasName if\n"
    "    <rateSecs> >int to rateSecs\n"
    "  then\n"
    "\n"
    "  rateSecs if\n"
    "    rateSecs \"Scan Pausing for %v secs\" str.format .\n"
    "    rateSecs task::sleepSsec\n"
    "    \"Scan awake\" .\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_DATAPULSE ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "// \": scan_DataMarker\" .\n"
    "\n"
    ": scan_DataMarker \\handler\n"
    " \n"
    "  debug::flag@ if \"(Revised) scan_DataMarker handler\" . then\n"
    "\n"
    "  // pipe out the pulse marker\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  // pipe out a new a stream def\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  // grab table ptn read lock\n"
    "  tablePtn[] tablePtnGrabRead\n"
    "\n"
    "  // new a partition stream for access crw buffer\n"
    "  tablePtn[] ptnStream::new to ptnStream[]\n"
    "\n"
    "  // open partition stream to access the crw buffers\n"
    "  ptnStream[] ptnStream.open if\n"
    "\n"
    "    // force op loop to call scan_CrwBuffer to start processing buffers\n"
    "    \"scan_CrwBuffer\" word::find LogicUnit[].handler!\n"
    "    true LogicUnit[].callAgain!\n"
    "\n"
    "  else\n"
    "    // unable to open partition stream (this would be unusual)\n"
    "\n"
    "    // delete partition stream\n"
    "    ptnStream[] ptnStream.delete\n"
    "    nullptr to ptnStream[]\n"
    "\n"
    "    // drop table ptn lock\n"
    "    tablePtn[] tablePtnDropRead\n"
    "\n"
    "    // send an eos marker (there was no data)\n"
    "    Operand[].newEosMarker\n"
    "    Operand[].pipeOut\n"
    "\n"
    "  then\n"
    " \n"
    "  true\n"
    " ;\n"
    "\n"
    "//  // -- partition stream test --\n"
    "//  tablePtn[] ptnStream::new to ptnStream[]\n"
    "//\n"
    "//  ptnStream[] ptnStream.open if\n"
    "//\n"
    "//    begin\n"
    "//      ptnStream[] ptnStream.read to Operand[]\n"
    "//      Operand[].isNull not\n"
    "//    while\n"
    "//      Operand[].pipeout\n"
    "//    repeat\n"
    "//\n"
    "//    ptnStream[] ptnStream.close\n"
    "//  then\n"
    "//\n"
    "//  ptnStream[] ptnStream.delete\n"
    "//  nullptr to ptnStream[]\n"
    "//  // -- end partition stream test --\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "// \": scan_StartMarker\" .\n"
    "\n"
    ": scan_StartMarker \\handler\n"
    "\n"
    "  <tableNm> op__table if\n"
    "    Table[].tablePtn@ to tablePtn[]\n"
    "    PipeIn[].pipeOut\n"
    "  then\n"
    "\n"
    "  //args.developer if\n"
    "  //  1 debug::flag!\n"
    "  //then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* scan request                                       (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scan_req \\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: scan_CancelMarker ZK_CANCELMARKER op[].handler!\n"
    "  find: scan_CrwBuffer    ZK_CRWBUFFER    op[].handler!\n"
    "  find: scan_DataMarker  ZK_DATAPULSE  op[].handler!\n"
    "  find: scan_StartMarker  ZK_STARTMARKER  op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: scan :: scan <tableNm> ;\n"
    "cmdSyntax: scan :: scan <tableNm> <rateSecs> ;\n"
    "\n"
    ": scan _cmdTags tagCopy: op_tags\n"
    "  tags{ <cmdDesc> = \"--desc for op--\" }\n"
    " ;\n"
    "  \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 86 CONSTANT OP_scan.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

