    "/* OP_syntaxTable.sen -- Operator syntax table                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_syntaxTable.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_DATAPULSE ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": syntaxTable_DataMarker\n"
    "\n"
    "  //job[] job.tagSet@ tagSet.asStr .\n"
    "\n"
    "  <etc> <tableNm> \"create table %v %v ;\" str.format dup .\n"
    "  job[] streamDef::parse to streamDef[]\n"
    "\n"
    "  streamDef[].isNull if\n"
    "    job[] job.error@\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in tables\n"
    "  folder[].isTables assert\n"
    "\n"
    "  Pipein[].pipeout\n"
    "  StreamDef[].pipeout\n"
    "\n"
    "  // should be in tables\n"
    "  folder[].isTables assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for syntaxTable req                        (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": syntaxTable_req \\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: syntaxTable_DataMarker ZK_DATAPULSE op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: syntaxTable :: syntaxTable <tableNm> <etc> ;\n"
    "\n"
    ": syntaxTable _cmdTags tagCopy: op_tags\n"
    "  tags{\n"
    "    <cmdDesc>   = \"--description of operator--\" }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

