  // munge of [103] test_dData.sen

  gszaMungedText[103] =
    "\" munged test_dData.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* test_dData.sen -- generate d test data                                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" test_dData.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate a d data file                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dDataFile\n"
    "\n"
    "  params| nRecs |\n"
    "  params| sFileNm |\n"
    "\n"
    "  nRecs sFileNm \"File: %v nRecs %v\" .printf\n"
    "\n"
    "  file::new locals| pFile |\n"
    "\n"
    "  sFileNm OPEN_WRITE pFile file.open\n"
    "  not if\n"
    "    \"file not opened\" .\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  nRecs 0 > if\n"
    "    nRecs 0\n"
    "    do\n"
    "      //I 0 \"%v,String%v\" str.format .\n"
    "      I 0 \"%v,String%v\\n\" str.format pFile file.writeLine\n"
    "    loop\n"
    "  then\n"
    "\n"
    "  pFile file.close\n"
    "\n"
    "  pFile file.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate the t data files                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dData\n"
    "\n"
    "  \"/rapids/d/d.csv\" 100000 dDataFile\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

