  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [106] se_str.sen

  gszaMungedText[106] =
    "\" munged se_str.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_str.sen -- additional str words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" se_str.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": str.isMetaToken ( s -- t|f )\n"
    "\n"
    "  dup 1 swap str.left  \"<\" str.same not if discard false exit_rt then\n"
    "\n"
    "  1 swap str.right \">\" str.same not if false exit_rt then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": str.isJsonToken ( s -- t|f )\n"
    "\n"
    "  \"{name:value}\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* convert str vector to path string                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": strVec::toPath ( s s s... n -- s )\n"
    "\n"
    "  // push initial result string\n"
    "  \"\" swap\n"
    "\n"
    "  ( n ) 0 ?do\n"
    "\n"
    "    \"/\" str.cat\n"
    "\n"
    "    swap str.cat\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* conver into into a string of digit names                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >digitWords ( i -- s )\n"
    "\n"
    "  >str locals| sDecodeMe |\n"
    "\n"
    "  \"\" \"\" 0 locals| iDigit sDigitName sDecodedTo |\n"
    "\n"
    "  // loop for 0 to length of sDecodeMe - 1\n"
    "  sDecodeMe str.length 0\n"
    "  do\n"
    "    // concat \" \" to end of decoded string\n"
    "    I if sDecodedTo \" \" str.cat to sDecodedTo then\n"
    "\n"
    "    // clip out digit I, convert it to a str\n"
    "    1 I sDecodeMe str.sub >int >digitName to sDigitName\n"
    "\n"
    "    // append digit name to the decoded string\n"
    "    sDecodedTo sDigitName str.cat to sDecodedTo\n"
    "  loop\n"
    "\n"
    "  // return decode string\n"
    "  sDecodedTo\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted print                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fmt.print\n"
    "\n"
    "  str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted put                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fmt.put\n"
    "\n"
    "  str.format .put\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 106 CONSTANT se_str.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

