    "\n"
    "  //pathStr .\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify and set folder to <tableNm>, then to <indexNm>                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__table_index ( tableNm indexNm )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  check::folderIsTables not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    PipeIn[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeOut\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // table\n"
    "  sTableNm check::validTableAssembly not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    PipeIn[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeOut\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // move to table folder and find the table\n"
    "  sTableNm path[].pushNamedTableFolder\n"
    "  sTableNm find execute to Table[]\n"
    "\n"
    "  // cross-check\n"
    "  Table[] assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // move to indexes folder\n"
    "  path[].pushIndexesFolder\n"
    "\n"
    "  sIndexNm check::nameIsaIndex not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    PipeIn[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeOut\n"
    "    path[].popNamedTableFolder\n"
    "    path[].popIndexesFolder\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  sIndexNm find execute to index[]\n"
    "\n"
    "  // cross-check\n"
    "  index[] assert\n"
    "\n"
    "  path[].popNamedTableFolder\n"
    "  path[].popIndexesFolder\n"
    "\n"
    "  //pathStr .\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* init rlu diary                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rluDiary_init\n"
    "\n"
    "  \"<note>\"  job[] job.tagSet@ tagSet.hasName if\n"
    "    <note> LogicUnit[].diaryJobNote\n"
    "  then\n"
    "\n"
    "  op.opName@ LogicUnit[].diaryTitle\n"
    "  op.opName@ Op.partition@ >str str.cat LogicUnit[].diaryName\n"
    "\n"
    "  <diaryDir> LogicUnit[].diaryDir\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set operator topology, next stage and op                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__topology\n"
    "\n"
    "  op[].init\n"
    "\n"
    "  // set topolgy in the op\n"
    "  <topology> op.topology!\n"
    "\n"
    "  // set nextStage in op\n"
    "  <nextStage> op.nextStage!\n"
    "\n"
    "  // set nextOp in op\n"
    "  <nextOp> op.nextOp!\n"
    "\n"
    "  \"<diary>\" job[] job.tagSet@ tagSet.hasName if\n"
    "    rluDiary_init\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* wait till pipeline job has stabilised                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__pipelineJobWait\n"
    "\n"
    "  // get the pipeline job of the operator\n"
    "  Op.pipelineJob@ locals| pPipelineJob |\n"
    "\n"
    "  //pPipelineJob job.jobList@  \"Job list %v\" .printf\n"
    "\n"
    "  // wait till the pipeline job is in a list\n"
    "  begin\n"
    "    pPipelineJob job.jobList@ JL_NONE ==\n"
    "  while\n"
    "    //pPipelineJob job.jobList@ \"Job list %v\" .printf\n"
    "    task::yield\n"
    "  repeat\n"
    "\n"
    "\n"
    "  // ensure pipeline job is executing and task is waiting\n"
    "  // for the non-demon jobs\n"
    "  pPipelineJob job.jobList@ JL_PARTICIPATING == if\n"
    "\n"
    "    // wait till the parent job is executing\n"
    "    begin\n"
    "      pPipelineJob job.phase@ JP_EXECUTING == not\n"
    "    while\n"
    "      //pPipelineJob job.phase@ \"Job phase %v\" .printf\n"
    "      task::yield\n"
    "    repeat\n"
    "\n"
    "    // wait till the pipelinetask is in a WAIT state\n"
    "    // possibilty of _execute not have arrived yet\n"
    "    pPipelineJob job.task@ locals| pPipelineTask |\n"
    "    begin\n"
    "      pPipelineTask task.isWaiting\n"
    "    not while\n"
    "      //pPipelineTask task.isWaiting \"task waiting %v\" .printf\n"
    "      task::yield\n"
    "    repeat\n"
    "\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* call handler for operand                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__handle params| pHandler iOperandKind |\n"
    "\n"
    "  0 iOperandKind EG_ZK LogicUnit[].diaryNote\n"
    "  pHandler execute\n"
    "  1 iOperandKind EG_ZK LogicUnit[].diaryNote\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return pipleine                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__returnPipeline\n"
    "\n"
    "\n"
    "  // find the __returnPipeline table def\n"
    "  C_TDEF_RETURNPIPELINE op__tableDef_infoSet assert\n"
    "\n"
    "  infoSetTable[] infoSet[].new\n"
    "    OI_RETURNPIPELINE infoSet[].opInfoset!\n"
    "\n"
    "  0 <reqOf> <reqNo> 3 InfoSet[].addRowVargs\n"
    "\n"
    "  InfoSet[]\n"
    "  nullptr to InfoSet[]\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* default operator loop                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__loop\n"
    "\n"
    "  0 0 locals| iOperandKind iOperandYield |\n"
    " \n"
    "  op__pipelineJobWait\n"
    "\n"
    "  begin\n"
    "\n"
    "    // attempt to get an Out-of_Order Operand\n"
    "    OperandOoO[].next if\n"
    "\n"
    "      OperandOoO[] to PipeIn[]\n"
    "      nullptr to OperandOoO[]\n"
    "\n"
    "      debug::flag@ if \"(Revised) Calling handler for OoO operand\" . then\n"
    "      PipeIn[].kind to iOperandKind\n"
    "\n"
    "      iOperandKind op[].isOperandValid not if\n"
    "        find: INVALID_OPERAND_handler op__handle\n"
    "      else\n"
    "        iOperandKind op[].IncOperandCount\n"
    "        iOperandKind dup op[].handler@ op__handle\n"
    "      then\n"
    "\n"
    "      PipeIn[].isNull assert\n"
    "\n"
    "    else\n"
    " \n"
    "      // test for call again\n"
    "      LogicUnit[].callAgain@ if\n"
    "\n"
    "        debug::flag@ if \"(Revised) Calling handler AGAIN operand\" . then\n"
    "\n"
    "        false LogicUnit[].callAgain!\n"
    "        true LogicUnit[].calledAgain!\n"
    "\n"
    "        iOperandKind op[].isOperandValid not if\n"
    "          find: INVALID_OPERAND_handler op__handle\n"
    "        else\n"
    "          iOperandKind op[].IncOperandCount\n"
    "          iOperandKind LogicUnit[].handler@ op__handle\n"
    "        then\n"
    "      else\n"
    " \n"
    "        iOperandYield 1 + to iOperandYield\n"
    "        iOperandYield task::operandYield@ >= if\n"
    "          task::yield\n"
    "          0 to iOperandYield\n"
    "        then\n"
    "\n"
    "        // bide till next operand is available\n"
    "        PipeIn[].bide\n"
    "\n"
    "        // pop next operand from queue into PipeIn[]\n"
    "        PipeIn[].next\n"
    "\n"
    "        // execute the operator's handler for the operand\n"
    "        debug::flag@ if \"(Revised) Calling handler for NEXT operand\" . then\n"
    "        PipeIn[].kind to iOperandKind\n"
    "\n"
    "        iOperandKind op[].isOperandValid not if\n"
    "          iOperandKind\n"
    "            find: INVALID_OPERAND_handler op__handle\n"
    "        else\n"
    "          iOperandKind op[].IncOperandCount\n"
    "\n"
    "          iOperandKind dup op[].handler@\n"
    "              dup LogicUnit[].handler!\n"
    "            op__handle\n"
    "        then\n"
    "\n"
    "        // assert Operand is null\n"
    "        PipeIn[].isNull assert\n"
    "\n"
    "      then\n"
    "  \n"
    "    then\n"
    "\n"
    "  while assert::stack_0 repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_TimerNew\n"
    "\n"
    "  timer::new    to timer[]\n"
    "  aggTimer::new to aggTimer[]\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_TimerBegin\n"
    "\n"
    "  timer[] timer.start\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_TimerUpdate\n"
    "\n"
    "  timer[] timer.update\n"
    "\n"
    "  timer[] timer.ticks aggTimer[] aggTimer.add\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

