  gszaMungedText[148] =
    "\" munged OP_progress.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_progress.sen -- Operator progress                                       */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_progress.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_EOSMARKER...                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": progress_EosMarker \\handler\n"
    "\n"
    "  <string> StringA[]\n"
    "    \"*** File: %v; %v Done ***\\n\" str.format .\n"
    "\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_PROGRESSUNITS...                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": progress_ProgressUnits \\handler\n"
    "\n"
    "  0 0 0 locals| nodeName partitionNo iPercent |\n"
    "\n"
    "  //\"Operand:- ZK_PROGRESSUNITS\" .verbose\n"
    "\n"
    "  // get operand into InfoSet[]\n"
    "  PipeIn[] to InfoSet[]\n"
    "  nullptr to PipeIn[]\n"
    "\n"
    "  // get first row of InfoSet[]\n"
    "  Infoset[].firstRow to row[]\n"
    "\n"
    "  // get 0th Column (ProgressUnits) add to Counter\n"
    "  0 row[].getIntColumn Counter1[] + to Counter1[]\n"
    "\n"
    "  // calculat the Load %\n"
    "  Counter1[] Counter0[] Int.percent to iPercent\n"
    "\n"
    "  // print the Load %\n"
    "  iPercent 0 > if\n"
    "    iPercent 100 >= if\n"
    "      <string> StringA[]\n"
    "          \"File: %v; %v Progress: 100\" str.format\n"
    "      \"%\\n\" str.cat .\n"
    "    else\n"
    "      iPercent <string> StringA[]\n"
    "         \"File: %v; %v Progress: %v\" str.format\n"
    "      \"%\" str.cat .\n"
    "    then\n"
    "  then\n"
    "\n"
    "\n"
    "  // now delete the InfoSet[]\n"
    "  InfoSet[].delete\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_TOTALUNITS...                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": progress_TotalUnits \\handler\n"
    "\n"
    "  0 locals| iPercent |\n"
    "\n"
    "  //\"Operand:- ZK_TOTALUNITS\" .verbose\n"
    "\n"
    "  // get operand into InfoSet[]\n"
    "  PipeIn[] to InfoSet[]\n"
    "  nullptr to PipeIn[]\n"
    "\n"
    "  // get first row of infoSet[]\n"
    "  Infoset[].firstRow to row[]\n"
    "\n"
    "  // get 0th Column (fileName)\n"
    "  0 row[].getVchColumn to StringA[]\n"
    "\n"
    "  // get 1st column (totalUnits)\n"
    "  1 row[].getIntColumn to Counter0[]\n"
    "\n"
    "  // now delete the InfoSet[]\n"
    "  InfoSet[].delete\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute for progress req                           (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    " : progress_req \\operator\n"
    " \n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: Progress_EosMarker     ZK_EOSMARKER     op[].handler!\n"
    "  find: Progress_ProgressUnits ZK_PROGRESSUNITS op[].handler!\n"
    "  find: Progress_TotalUnits    ZK_TOTALUNITS    op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: progress :: progress <string> ;\n"
    "\n"
    ": progress _cmdTags tagCopy: op_tags\n"
    "  tags{ <cmdDesc> = \"--desc for op--\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

