  // munge of [150] BM_genEnt.sen

  gszaMungedText[150] =
    "\" munged BM_genEnt.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* BM_genEnt.sen -- Benchmark Operator genEnt                                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" BM_genEnt.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_DATAPULSE ...                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "//: BM_GenEnt_DataMarker \\handler\n"
    "//\n"
    "//  // pipe out the pulse marker to the next operator\n"
    "//  Operand[].pipeOut\n"
    "//\n"
    "//  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "//\n"
    "//  // new a stream def\n"
    "//  Operand[].newStreamDef\n"
    "//\n"
    "//  Operand[].pipeOut\n"
    "//\n"
    "//  // generate the ent buffer's\n"
    "//  <nBuffers> index[].genEntBuffers to Operand[]\n"
    "//  Operand[].pipeOutSet\n"
    "//\n"
    "//  Operand[].newEosMarker\n"
    "//  Operand[].pipeOut\n"
    "//\n"
    "//  true\n"
    "//;\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_GenEnt_DataMarker \\handler\n"
    "\n"
    "  // pipe out the pulse marker to the next operator\n"
    "  PipeIn[].pipeOut\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pipeout a new stream def\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // generate the ent buffer's\n"
    "  <nBuffers> >int 0 do\n"
    "    index[].genEntBuffer to Operand[]\n"
    "    Operand[].pipeOut\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pipeout a new eos marker\n"
    "\n"
    "  Operand[].newEosMarker\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* on ZK_STARTMARKER ...                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_GenEnt_StartMarker \\handler\n"
    "\n"
    "  \"BM_GenEnt_StartMarker\" .\n"
    "\n"
    "  <tableNm> <indexNm> op__table_index if\n"
    "\n"
    "    path[].toStr     \"Folder path: %v\" .printf\n"
    "    folder[].contentStr \"contains: %v\" .printf\n"
    "\n"
    "    PipeIn[].pipeOut\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* BM_GenEntOp request                                (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_GenEntOp_req \\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: BM_GenEnt_DataMarker ZK_DATAPULSE op[].handler!\n"
    "  find: BM_GenEnt_StartMarker ZK_STARTMARKER op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  \"*** BM_GenEntOp EXITS\" .\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: BM_GenEntOp :: BM_GenEntOp <tableNm> <indexNm> <nBuffers> ;\n"
    "\n"
    ": BM_GenEntOp _cmdTags tagCopy: op_tags\n"
    "  tags{ <cmdDesc>  = \"--desc for op--\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 150 CONSTANT BM_genEnt.sen "_Stz;
