  // munge of [153] OP_listTableDefs.sen

  gszaMungedText[153] =
    "\" munged OP_listTableDefs.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_listTableDefs.sen -- Operator list table definitions                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" OP_listTableDefs.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lstbldef_action\n"
    "\n"
    "  0 0 locals| sTableNm pTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in the tables folder\n"
    "  check::folderIsTables not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    PipeIn[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeOut\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // find the __ table\n"
    "  <streamDef> op__tableDef_streamSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  streamSetTable[] streamDef[].new\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  streamDef[].pipeOut\n"
    "\n"
    "  // create an infoSet operand\n"
    "  streamSetTable[] StreamSet[].new\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // insert a row in teh infoSet for each word\n"
    "\n"
    "  folder[] dic.lastWord dup\n"
    "  iterate                          // setup iteration of words\n"
    "\n"
    "    object@ word.name@ to sTableNm\n"
    "    sTableNm path[].pushNamedTableFolder\n"
    "    sTableNm find execute to Table[]\n"
    "\n"
    "    // skip definition only tables\n"
    "    Table[].isDefinitionOnly@ if\n"
    "\n"
    "    sTableNm streamSetTable[] StreamSet[].addListContents  not if\n"
    "      StreamSet[].pipeOut\n"
    "      streamSetTable[] streamSet[].new\n"
    "      sTableNm streamSetTable[] StreamSet[].addListContents assert\n"
    "    then\n"
    "\n"
    "\n"
    "    then\n"
    "\n"
    "    \"path[].popNamedTableFolder\" find execute\n"
    "\n"
    "    object@ word.prev object!      // step backwards thru words\n"
    "  next\n"
    "\n"
    "  // pipeout the infoset\n"
    "  StreamSet[].pipeOut\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "cmdSyntax: lstbldef :: lstbldef ;\n"
    "\n"
    ": lstbldef _cmdTags tagCopy: localLiteOp_tags\n"
    "  tags{\n"
    "    <cmdDesc>     = \"--desc for op--\"\n"
    "    <streamDef>   = __listContents\n"
    "    <params>      = 0\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

