  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [158] db_table.sen

  gszaMungedText[158] =
    "\" munged db_table.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_table.sen -- table related words                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" db_table.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* the table category                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\table \\\\category ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if word is a table (is of \\table category)                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word.isaTable params| pwTable | ( t | f )\n"
    "\n"
    "  pwTable word.category@ find: \\table eql\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if current folder has the name \"tables\" (i.e. is ../tables)           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder[].isTables ( t | f )\n"
    "\n"
    "  folder[] dic.name@ \"tables\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the named table folder and push it onto task dictionary               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": path[].pushNamedTableFolder params| sTblFolderNm |\n"
    "\n"
    "  sTblFolderNm find execute path[].pushFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop current folder (which was pushed by path[].pushNamedTableFolder)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": path[].popNamedTableFolder ( -- )\n"
    "\n"
    "  path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check current folder has the name \"tables\" (i.e. is ../tables)          EC */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::folderIsTables ( t | ec f )\n"
    "\n"
    "  folder[].isTables if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check there is a table folder with given name                           EC */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::folderHasNamedTable params| sTblFolderNm | ( t | ec f )\n"
    "\n"
    "  sTblFolderNm folder[].findSymbol not if EC_NO_SUCH_TABLE false exit then\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is not known (specifically not a known table)                EC */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::nameIsUnknownTable params| sTableNm | ( t | ec f )\n"
    "\n"
    "  sTableNm folder[].findSymbol not if true exit then\n"
    "  EC_TABLE_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check given name is the name of a word of \\table category               EC */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::nameIsaTable params| sTableNm | ( t | ec f )\n"
    "\n"
    "  sTableNm find locals| pwTable |\n"
    "\n"
    "  pwTable not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  pwTable word.category@ find: \\table eql if true exit then\n"
    "\n"
    "  EC_NOT_A_TABLE false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if column is a valid column of the table                          EC */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::nameIsColumn params| sTableNm sColumnNm | ( t | ec f )\n"
    "\n"
    "  0 locals| pTable |\n"
    "\n"
    "  sTableNm find execute to pTable\n"
    "  sColumnNm pTable table.isColumn if true exit then\n"
    "\n"
    "  EC_INVALID_COLUMN false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if given name is a valid table assembly                           EC */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": check::validTableAssembly params| sTableNm | ( t | ec f )\n"
    "\n"
    "  // check we are in tables folder\n"
    "  check::folderIsTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm word::isKnown not if discard EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm path[].pushNamedTableFolder\n"
    "\n"
    "  // check if sTableNm translates to a word of \\table category\n"
    "  sTableNm check::nameIsaTable not if path[].popNamedTableFolder false exit then\n"
    " \n"
    "  // pop table folder\n"
    "  path[].popNamedTableFolder\n"
    "\n"
    "  // assert we are back in tables\n"
    "  folder[].isTables assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                          -- Create Table Support --                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make the \"tables\" folder under given named schema folder                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::makeTablesFolder params| sSchFolderNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    \"MAKING TABLES FOLDER FOR SCHEMA \" sSchFolderNm str.cat\n"
    "      \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  sSchFolderNm find execute locals| pwSchemaFolder |\n"
    "  \"tables\" pwSchemaFolder folder::makeSubFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a table folder under a tables folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::makeNamedTableFolder params| sTblFolderNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    \"MAKING TABLE \" sTblFolderNm str.cat\n"
    "     \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // make: ../schemas/public/tables/t \\folder\n"
    "  sTblFolderNm folder[] folder::makeSubFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* new a c++ Table instance using given table name                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::newTable params| sTableNm | ( pTable )\n"
    "\n"
    "  find: \\table locals| pwTableCatg |\n"
    "\n"
    "  sTableNm table::new locals| pTable |\n"
    "\n"
    "  sTableNm word::new locals| pwTable |\n"
    "\n"
    "  pwTableCatg pTable pwTable word.cppObject!\n"
    "\n"
    "  //pwTable word.see\n"
    "\n"
    "  pwTable execute locals| pTable |\n"
    "\n"
    "  pTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a table assembly (along with indexes sub-assembly)                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::makeTableAssembly params| sTableNm pStreamDef | ( pTable )\n"
    "\n"
    " sTableNm table::makeNamedTableFolder\n"
    "\n"
    " sTableNm path[].pushNamedTableFolder\n"
    "\n"
    " sTableNm \"index::makeIndexesAssembly\" find execute\n"
    "\n"
    " sTableNm table::newTable locals| pTable |\n"
    "\n"
    " pStreamDef pTable table.streamDef!\n"
    "\n"
    " pTable table.createPtnDef\n"
    "\n"
    " path[].popNamedTableFolder\n"
    "\n"
    " pTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using given table definition                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::createTable params| sTableNm pStreamDef | ( pTable )\n"
    "\n"
    " folder[].isTables assert\n"
    " sTableNm name::isSubFolder not assert\n"
    "\n"
    " pStreamDef sTableNm table::makeTableAssembly locals| pTable |\n"
    "\n"
    " folder[].isTables assert\n"
    " sTableNm name::isSubFolder assert\n"
    "\n"
    " pTable\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                          -- Drop Table Support --                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* delete C++ Table object & its forget word                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::deleteTable params| sTableNm |\n"
    "\n"
    "  sTableNm find execute table::delete\n"
    "\n"
    "  sTableNm :forget\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a table assembly (along with indexes sub-assembly)                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::removeTableAssembly params| sTableNm |\n"
    "\n"
    "  // path: /tenants/boray/catalogs/rapidsse/schemas/public/tables\n"
    "\n"
    "  // push to named table folder\n"
    "  sTableNm path[].pushNamedTableFolder\n"
    "\n"
    "  // ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++ ++\n"
    "\n"
    "    // path: /tenants/boray/catalogs/rapidsse/schemas/public/tables/t\n"
    "\n"
    "    // remove the index sub-assembly for this table\n"
    "    \"index::removeIndexesAssembly\" find execute\n"
    "\n"
    "    // delete c++ Table object and forget the table word\n"
    "    sTableNm table::deleteTable\n"
    "\n"
    "    // pop back to table\n"
    "    path[].popNamedTableFolder\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // path: /tenants/boray/catalogs/rapidsse/schemas/public/tables\n"
    "\n"
    "  // forget the named table folder\n"
    "  sTableNm folder::remove\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop named table (remove the table assembly and indexes sub-assembly)      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": table::dropTable params| sTableNm |\n"
    "\n"
    "  /*\n"
    "   * This is called from : dropTable_DataMarker in procedure drop table\n"
    "   *\n"
    "   * At this stage the table (and its indexes) will have been truncated\n"
    "   * All that remains to be done is remove the table and indexes assemblies\n"
    "   *\n"
    "   */\n"
    "\n"
    "  // path: /tenants/boray/catalogs/rapidsse/schemas/public/tables\n"
    "\n"
    "  sTableNm name::isSubFolder assert\n"
    "\n"
    "  sTableNm table::removeTableAssembly\n"
    "\n"
    "  sTableNm name::isSubFolder not assert\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

