    "//      unloop\n"
    "//      false\n"
    "//      exit\n"
    "//    then\n"
    "//  loop\n"
    "//\n"
    "//  \"All nodes connected\" .verbose\n"
    "//\n"
    "//  true\n"
    "//;\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::connected ( -- t|f )\n"
    "\n"
    "  0 locals| pNode |\n"
    "\n"
    "  node_I[].new\n"
    "\n"
    "  begin\n"
    "    node_I[].node to pNode\n"
    "\n"
    "    pNode node.isConnected not if\n"
    "      args.verbose if\n"
    "        pNode node.no \"Node no %v not connected\" .printf\n"
    "        node_I[].delete\n"
    "        false\n"
    "        exit\n"
    "      then\n"
    "    then\n"
    "\n"
    "    node_I[].next\n"
    "    node_i[].more while\n"
    "  repeat\n"
    "\n"
    "  node_I[].delete\n"
    "\n"
    "  \"All nodes connected\" .verbose\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": grid::pause ( -- )\n"
    "\n"
    "  begin\n"
    "    grid::connected not\n"
    "  while\n"
    "    100 thread::sleepMsec\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to wait for cluster to connect (on originating node)               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": connectCluster_req ( -- <R> )\n"
    "\n"
    "\n"
    "  task::seedInitially\n"
    "\n"
    "  // [ compiler::current@ word.name@ encode::push ] .\n"
    "  // <jobNm> .\n"
    "\n"
    "  job::becomeOriginator\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // has cluster already been started?\n"
    "\n"
    "  grid::started@ if\n"
    "                                             //! how do we set an error message?\n"
    "    DONE_REQ\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn all other nodes\n"
    "\n"
    "  grid::setStartNode\n"
    "\n"
    "  //grid::spawnOtherNodes\n"
    "\n"
    "  //connector::spawn\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pause till all nodes connected\n"
    "\n"
    "  grid::pause\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the start cluster job\n"
    "\n"
    "  job::distributeConnected\n"
    "\n"
    "  // wait for the signal from deciding job__ended/cancelled\n"
    "  task::wait\n"
    "\n"
    "  // set grid as started\n"
    "  true grid::started!\n"
    "  \"Cluster started\" .\n"
    "\n"
    "  task::doneFinally\n"
    "\n"
    "  //\"Signalling waiting thread\" .\n"
    "  job::informInvokerOfCompletion\n"
    "  // task has no job\n"
    "  task::scheduledelete\n"
    "\n"
    "  HAZARD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute job_ConnectCluster (on participating node)                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": connectCluster::execute _eeh ( -- )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // wait till all nodes connected\n"
    "  grid::pause\n"
    "\n"
    "  true grid::started!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "cmdSyntax: connectCluster :: connectCluster ;\n"
    "\n"
    ": connectCluster _cmdTags tagCopy: distJob_tags\n"
    "  tags{\n"
    "    <rspKind>  = RS_NONE\n"
    "    <ddlLock>  = DL_NONE\n"
    "  }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\n"
    ""_Stz
  ;

