  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [170] job__Ended.sen

  gszaMungedText[170] =
    "\" munged job__Ended.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__Ended.sen -- generic job related words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" job__Ended.sen\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on participating node                           //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* send Job__Ended back to originating node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Job__Ended::send ( pJobParticipant -- )\n"
    "\n"
    "  params| pJobParticipant |\n"
    "\n"
    "  pJobParticipant job.id@ locals| iJobId |\n"
    "\n"
    "  0 locals| pJob__Ended |\n"
    "\n"
    "  //grid::thisNodeName@ \"(%v) ENDED::send\" .printf\n"
    "\n"
    "  // new a temporary Job__Ended\n"
    "  pJobParticipant job__Ended::new to pJob__Ended\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // set the originator node as the send target node\n"
    "  //iJobId job::originator@ grid::node task[] task.sendNode!\n"
    "\n"
    "  // send the ended job\n"
    "  iJobId job::originator@ pJob__Ended job.reply\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  pJob__Ended job.delete\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on originating node                             //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* run received Job__Ended on originating node       recv: job.spawn_received */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": _Ended _run\n"
    "\n"
    "  job[] locals| pJob__Ended |\n"
    "  pJob__Ended job.id@ locals| iJobId |\n"
    "\n"
    "  0 locals| bAmDecider |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the context of this __ended job\n"
    "\n"
    "  // find the originating job\n"
    "  iJobId olist::findJob discard\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // process __ended job on this originating node\n"
    "\n"
    "  // increment the number of __ended jobs received in api state\n"
    "  JobRef[] ssn::incEnded\n"
    "  JobRef[] ssn::traceSession\n"
    "\n"
    "  // decrement the acks remaining\n"
    "  JobRef[] job.dec2pcAcksRmg to bAmDecider\n"
    "\n"
    "  //grid::thisNodeName@ \"(%v) ENDED GOT ACK\" .printf\n"
    "  // if there are acks remaining just exit\n"
    "  bAmDecider not if\n"
    "    JobRef[].return\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "  //grid::thisNodeName@ \"(%v) ENDED AM DECIDER\" .printf\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // all __ended jobs have been received, so this job is the decider\n"
    "\n"
    "  begin\n"
    "    JobRef[].references\n"
    "  1 > while\n"
    "  repeat\n"
    "\n"
    "  // remove the originating job from the originator jobs\n"
    "  JobRef[] job.removeOriginator\n"
    "\n"
    "  JP_ENDED log::markPhase\n"
    "\n"
    "  // notify the originating task\n"
    "  //JobRef[] job.originatingTask@ task.ack\n"
    "  JobRef[] job.task@ task.ack\n"
    "  JobRef[].return\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "cmdSyntax: _Ended :: _Ended ;\n"
    "\n"
    ": _Ended _cmdTags tagCopy: genericJob_tags\n"
    "  tags{\n"
    "    <cmdDesc>  = \"--desc for job--\"\n"
    "  }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 170 CONSTANT job__Ended.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of [171] db_partition.sen

  gszaMungedText[171] =
    "\" munged db_partition.sen \" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_partition.sen -- partition related words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\" db_partition.sen\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a partitions folder under given named table                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makePartitions ( \"<tableNm>\" -- )\n"
    "\n"
    "  params| tableNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    tableNm \"MAKING PARTITIONS FOR TABLE \" swap str.cat \" on NODE \" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tableNm find execute ( dic )\n"
    "  \"partitions\" ( dic \"partitions\" )\n"
    "  swap         ( \"partitions\" dic )\n"
    "  folder::makeSubFolder   ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within partitions folder                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder[].isPartitions\n"
    "  folder[] dic.name@ \"partitions\" str.same\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in partitions folder                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInPartitions\n"
    "  folder[].isPartitions if true exit then\n"
    "  EC_NOT_IN_PARTITIONS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the partitions folder and push it onto task dictionary                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushPartitions ( -- )\n"
    "  \"partitions\" find execute path[].pushFolder\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the partitions folder                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popPartitions\n"
    "  path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the partition sub folder                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popPartitionSub\n"
    "  path[].popFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is partitions                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInPartitions ( -- t|f )\n"
    "  folder[].isPartitions assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab write lock on a partition of given table                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnGrabWrite ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |   // table partition\n"
    "\n"
    "  begin\n"
    "    pTablePtn tablePtn.attemptGrabWrite\n"
    "  not while\n"
    "    task::yield\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab write lock on given table ptn (with 1ms sleep loop till grabbed)      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnGrabWrite_msec params| pTablePtn |\n"
    "\n"
    "  begin\n"
    "    pTablePtn tablePtn.attemptGrabWrite\n"
    "  not while\n"
    "    1 task::sleepMsec\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* grab read lock on a partition of given table                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnGrabRead ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |   // table partition\n"
    "\n"
    "  begin\n"
    "    pTablePtn tablePtn.attemptGrabRead\n"
    "  not while\n"
    "    task::yield\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop read lock on a partition of given table                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnDropRead ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |  // given tablePtn\n"
    "\n"
    "  pTablePtn tablePtn.dropRead\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop write lock on a partition of given table                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tablePtnDropWrite ( pTablePtn -- )\n"
    "\n"
    "  params| pTablePtn |  // given tablePtn\n"
    "\n"
    "  pTablePtn tablePtn.dropWrite\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    ""_Stz
  ;

  szSubScriptDef = " 171 CONSTANT db_partition.sen "_Stz;
  vCompileMungedColon(szSubScriptDef);

